{
  "name": "ExpensiveOnlineOrderFromUnseenDevice",
  "description": "Detects an online order from a device we have never seen, indicating potential account takeover.",
  "severity": "high",
  "action": "block",
  "logic": "any",
  "conditions": [
    {
      "field": "amount",
      "op": ">",
      "value": 500
    },
    {
      "field": "is_new_device",
      "op": "==",
      "value": true
    },
    {
      "field": "txn_count_24h",
      "op": ">",
      "value": 1
    }
  ],
  "rationale": "This rule flags an online order that is significantly larger than the customer's usual spending, indicating potential account takeover. The device is new, and there has been only one transaction in the past 24 hours, which is a strong indicator of account takeover."
}

{
  "name": "High-SpendingUnfamiliarDeviceIPMismatch",
  "description": "Detects online purchases over $500 from an unfamiliar device with an IP address in a different country from the cardholder's home country.",
  "severity": "critical",
  "action": "block",
  "logic": "all",
  "conditions": [
    {
      "field": "amount",
      "op": ">",
      "value": 500
    },
    {
      "field": "is_new_device",
      "op": "==",
      "value": true
    },
    {
      "field": "ip_country_mismatch",
      "op": "==",
      "value": true
    }
  ],
  "rationale": "This rule flags transactions that exceed $500, are from an unfamiliar device, and have an IP address in a different country from the cardholder's home country, which is a strong indicator of fraud."
}

{
  "name": "HighSpendingWithin24Hours",
  "description": "Detects accounts that open recently and spend thousands of dollars in a single day.",
  "severity": "high",
  "action": "block",
  "logic": "all",
  "conditions": [
    {
      "field": "account_age_days",
      "op": "<",
      "value": 30
    },
    {
      "field": "amount_sum_24h",
      "op": ">",
      "value": 1000
    },
    {
      "field": "hour_of_day",
      "op": "==",
      "value": 23
    }
  ],
  "rationale": "This rule flags accounts that open recently and spend a significant amount in a single day, which is a common pattern for fraud."
}

{
  "name": "SyntheticIdentitiesLargeSpending",
  "description": "Detects accounts less than a month old buying gift cards or electronics in large amounts.",
  "severity": "medium",
  "action": "review",
  "logic": "all",
  "conditions": [
    {
      "field": "account_age_days",
      "op": "<",
      "value": 30
    },
    {
      "field": "merchant_category",
      "op": "in",
      "value": ["gift_cards", "electronics"]
    },
    {
      "field": "amount",
      "op": ">=",
      "value": 1000
    }
  ],
  "rationale": "This rule flags accounts that are less than a month old and are making large purchases in gift cards or electronics, which is a common tactic for synthetic identities to bypass fraud detection."
}

