{
  "name": "ATM Cashout Fraud",
  "description": "Detects skimming cards being cashed out at ATMs abroad with transactions in more than one country on the same day.",
  "severity": "high",
  "action": "block",
  "logic": "all",
  "conditions": [
    {
      "field": "is_international",
      "op": "==",
      "value": true
    },
    {
      "field": "is_new_device",
      "op": "==",
      "value": true
    },
    {
      "field": "amount_to_avg_ratio",
      "op": "between",
      "value": [1.5, 2.5]
    },
    {
      "field": "distinct_countries_24h",
      "op": ">", 
      "value": 2
    }
  ],
  "rationale": "This rule flags transactions where skimming cards are used to cash out abroad, with multiple transactions in different countries on the same day, which is a strong indicator of fraud."
}

